  const lower=row.text.toLowerCase();if(!lower.includes(suggestion.from.toLowerCase()))continue;
  const wanted=suggestion.from.toLowerCase().split(/\s+/),words=(row.words||[]).filter(w=>wanted.includes(String(w.text||'').toLowerCase().replace(/^[^a-zäöüß]+|[^a-zäöüß]+$/gi,''))&&w.bbox),boxes=words.length?words.map(w=>w.bbox):[row.bbox];
