   if(accept){if(field.value.slice(suggestion.start,suggestion.end)!==suggestion.from){renderContextReview();return;}field.value=field.value.slice(0,suggestion.start)+suggestion.to+field.value.slice(suggestion.end);contextChanges.push(suggestion.from+' → '+suggestion.to);invalidateReview();previewUncertainty();status((suggestion.quantity?'Mengenvorschlag':'Wortvorschlag')+' übernommen. Rezept vor dem Speichern vollständig prüfen.');}
