function importREKEKDraft(draft){window.dispatchEvent(new Event('reserve:personal-source-changed'));resetContextReview();showRowReview([]);if(!draft||typeof draft.title!=='string'||!Array.isArray(draft.ingredients)||!Array.isArray(draft.sourceExpressions)||draft.ingredients.length!==draft.sourceExpressions.length||draft.ingredients.length>500)throw Error('Ungültiger REKEK-Entwurf.');const expressions=draft.sourceExpressions.map(row=>{const text=row?.normalizedExpression||row?.originalOCRExpression;if(typeof text!=='string'||text.length>2000)throw Error('Ungültige Zutatenzeile.');return text});let steps=draft.steps;if(!Array.isArray(steps))steps=(draft.preparationVariants||[]).map(v=>v.text);if(!Array.isArray(steps)||!steps.every(x=>typeof x==='string'))throw Error('Ungültige Zubereitung.');$('personalName').value=draft.title.slice(0,200);$('personalPortions').value='';$('personalPrep').value='';$('personalCook').value='';$('personalSource').value='';$('personalDiet').value='Alles';$('personalIngredients').value=expressions.join('\n');$('personalSteps').value=steps.join('\n');invalidateReview();previewUncertainty();status('REKEK-Testentwurf: OCR-Angaben können falsch sein. Ungeklärte Mengen und Zutatenvarianten am Original prüfen; nichts zusammenzählen. Portionen und Schrittaufteilung ergänzen.');}
