  try{if(typeof createImageBitmap==='function')image=await createImageBitmap(file)}catch{}
  if(!image){url=URL.createObjectURL(file);image=await new Promise((resolve,reject)=>{const img=new Image(),timer=setTimeout(()=>{img.src='';reject(Error('Bild konnte nicht geöffnet werden.'))},15000);img.onload=()=>{clearTimeout(timer);resolve(img)};img.onerror=()=>{clearTimeout(timer);reject(Error('Bild konnte nicht geöffnet werden.'))};img.src=url})}
