 const heading=document.createElement('h3');heading.textContent=rows.some(r=>r.kind==='step')?'Rezeptzeilen prüfen':'Zutatenzeilen prüfen';const note=document.createElement('p');note.textContent='Übereinstimmung ist keine Bestätigung. Abweichende Mengen bleiben ungeklärt. Jede Zeile am Original prüfen.';
